  // ========== CORE ROUTER ENGINE INTERCEPTOR ==========
  document.addEventListener("DOMContentLoaded", () => {
    if (typeof window.doEsSearch === "function") {
      const coreEsSearch = window.doEsSearch;

      window.doEsSearch = function (val) {
        if (!val || !val.trim()) return;
        const query = val.trim();
        const lowerQuery = query.toLowerCase();

        // 1. CRITICAL OVERRIDE: Nikhil Creator Profile Telemetry (Easter Egg)
        if (lowerQuery === 'nikhil' || lowerQuery === '@nikhil' || lowerQuery === 'x0s creator') {
          handleExtendedExecution(query, () => executeCreatorTelemetry());
          return;
        }

        // 2. ADVANCED MATHEMATICAL PARSER DETECTOR
        const mathSignals = ['sin', 'cos', 'tan', 'log', 'ln', 'sqrt', 'pow', 'pi', 'solve', 'quad', 'd/dx', 'bin', 'hex', 'oct'];
        const standardMathPattern = /^[0-9\s+\-*/().^%x=]+$/.test(query);
        const containsOperator = /[+\-*/=]/.test(query);

        if (mathSignals.some(sig => lowerQuery.includes(sig)) || (standardMathPattern && containsOperator)) {
          handleExtendedExecution(query, () => executeAdvancedMath(query));
          return;
        }

        // 3. TELEMETRY SYSTEM: Live Weather Module
        if (lowerQuery.startsWith('weather') || lowerQuery.includes('temperature') || lowerQuery.includes('forecast')) {
          const cityMatch = query.replace(/(weather|temperature|forecast|in|at|\s)/gi, '');
          const targetCity = cityMatch || CONFIG.defaultCity;
          handleExtendedExecution(query, () => fetchLiveWeatherTelemetry(targetCity));
          return;
        }

        // 4. KNOWLEDGE BASE MATRIX LOOKUP (Definitions & GK Arrays)
        if (executeKnowledgeLookup(lowerQuery)) {
          return;
        }

        // 5. CORE FALLBACK (Standard profiles/colleges pipeline)
        coreEsSearch(val);
      };
    }
  });

  // ========== INTERFACE SEQUENCE COORDINATOR ==========
  function handleExtendedExecution(userQuery, executionCallback) {
    document.getElementById('es-input').value = '';
    document.getElementById('es-send').classList.remove('visible');
    document.getElementById('es-suggestions').style.display = 'none';

    const greet = document.getElementById('es-greeting');
    if (greet) greet.style.display = 'none';

    if (typeof window.appendEsBubbleUser === 'function') {
      window.appendEsBubbleUser(userQuery);
    }

    setTimeout(() => {
      executionCallback();
      if (typeof window.scrollEsToBottom === 'function') {
        window.scrollEsToBottom();
      }
    }, 280);
  }

