  // ========== EXPANSION WORKSPACE 2: ADVANCED MATH KERNEL ==========
  function executeAdvancedMath(rawExpr) {
    const container = document.getElementById('es-messages');
    const sysBubble = document.createElement('div');
    sysBubble.className = 'es-bubble-sys';

    let kernelType = "SCIENTIFIC MATHEMATICS";
    let computedResult = "";
    let systemNotes = "Parser evaluation successful.";
    let isError = false;

    let input = rawExpr.toLowerCase().replace(/solve|calculate|eval/g, '').trim();

    try {
      if (input.includes('x^2') || input.includes('x²')) {
        kernelType = "ALGEBRA ROOT MODULE";
        let cleanInput = input.replace(/\s+/g, "");
        if (!cleanInput.includes("=0")) cleanInput += "=0";
        
        const match = cleanInput.match(/([+-]?\d*)x\^2([+-]?\d*)x([+-]?\d*)=0/) || cleanInput.match(/([+-]?\d*)x²([+-]?\d*)x([+-]?\d*)=0/);
        if (match) {
          let a = parseFloat(match[1] === "" || match[1] === "+" ? 1 : match[1] === "-" ? -1 : match[1]);
          let b = parseFloat(match[2] === "" || match[2] === "+" ? 1 : match[2] === "-" ? -1 : match[2]);
          let c = parseFloat(match[3] || 0);
          
          let disc = b * b - 4 * a * c;
          if (disc > 0) {
            computedResult = `x₁ = ${((-b + Math.sqrt(disc)) / (2 * a)).toFixed(4)}<br>x₂ = ${((-b - Math.sqrt(disc)) / (2 * a)).toFixed(4)}`;
          } else if (disc === 0) {
            computedResult = `x = ${(-b / (2 * a)).toFixed(4)} (Repeated Root)`;
          } else {
            let r = (-b / (2 * a)).toFixed(4);
            let img = (Math.sqrt(-disc) / (2 * a)).toFixed(4);
            computedResult = `x₁ = ${r} + ${img}i<br>x₂ = ${r} - ${img}i`;
          }
          systemNotes = `Discriminant Matrix (Δ) = ${disc}`;
        } else {
          throw new Error("Syntax mismatch. Input format: ax^2+bx+c=0");
        }
      } 
      else if (input.startsWith('d/dx')) {
        kernelType = "CALCULUS ENVELOPE Engine";
        const pointMatch = input.match(/at\s+([+-]?\d*\.?\d*)/);
        if (!pointMatch) throw new Error("Missing assignment. Set target point: 'at [value]'");
        
        let targetX = parseFloat(pointMatch[1]);
        let exprBody = input.match(/d\/dx\(([^)]+)\)/);
        if (!exprBody) throw new Error("Could not parse explicit boundaries.");
        
        let targetExpr = exprBody[1];
        const evaluateAt = (x) => {
          let mathParsed = targetExpr.replace(/x/g, `(${x})`).replace(/\^/g, "**");
          return Function(`"use strict"; return (${mathParsed})`)();
        };

        const step = 0.00001;
        let derivative = (evaluateAt(targetX + step) - evaluateAt(targetX - step)) / (2 * step);
        computedResult = `f'( ${targetX} ) ≈ ${derivative.toFixed(5)}`;
        systemNotes = `Numerical approximation via finite difference derivative calculation matrix.`;
      } 
      else {
        let executionCode = input
          .replace(/sin\(/g, "Math.sin(")
          .replace(/cos\(/g, "Math.cos(")
          .replace(/tan\(/g, "Math.tan(")
          .replace(/sqrt\(/g, "Math.sqrt(")
          .replace(/log\(/g, "Math.log10(")
          .replace(/ln\(/g, "Math.log(")
          .replace(/\^/g, "**")
          .replace(/pi/g, "Math.PI")
          .replace(/e/g, "Math.E");

        let evalOut = Function(`"use strict"; return (${executionCode})`)();
        
        if (typeof evalOut === 'number') {
          computedResult = Number.isInteger(evalOut) ? evalOut.toString() : evalOut.toFixed(6).replace(/\.?0+$/, "");
        } else {
          computedResult = evalOut !== undefined ? evalOut.toString() : "Void evaluation output frame.";
        }
      }
    } catch (err) {
      computedResult = err.message || "Engine evaluation conflict.";
      systemNotes = "Math compilation stack fault.";
      isError = true;
    }

    const card = document.createElement('div');
    card.className = 'es-result-card';
    card.style.borderLeft = isError ? '3px solid #ff3b5c' : '3px solid #007aff';
    card.style.background = '#0a0a0a';

    card.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
        <span style="font-size:0.58rem; font-weight:700; color:${isError ? '#ff3b5c' : '#007aff'}; letter-spacing:0.1em; text-transform:uppercase;">
          <i class="fa-solid fa-microchip" style="margin-right:4px;"></i> ${kernelType}
        </span>
        <span style="font-size:0.55rem; color:#666; font-family:monospace;">CORE_RUN</span>
      </div>
      <div style="font-size:0.7rem; color:#666; font-family:monospace; margin-bottom:4px;">INP // ${rawExpr}</div>
      <div style="font-size:1.05rem; font-weight:700; color:${isError ? '#ff3b5c' : '#fff'}; line-height:1.35;">${computedResult}</div>
      <div style="margin-top:8px; padding-top:6px; border-top:1px dashed #1a1a1a; font-size:0.6rem; color:#444;">
        <i class="fa-solid fa-circle-info" style="margin-right:4px;"></i> ${systemNotes}
      </div>
    `;

    sysBubble.appendChild(card);
    container.appendChild(sysBubble);
  }

  // ========== EXPANSION WORKSPACE 3: LIVE WEATHER TELEMETRY ==========
  function fetchLiveWeatherTelemetry(city) {
    const container = document.getElementById('es-messages');
    const sysBubble = document.createElement('div');
    sysBubble.className = 'es-bubble-sys';

    const card = document.createElement('div');
    card.className = 'es-result-card';
    card.style.background = '#0a0a0a';
    card.style.borderLeft = '3px solid #007aff';
    card.innerHTML = `<div style="font-size:0.78rem; color:#666;"><i class="fa-solid fa-spinner fa-spin" style="margin-right:6px;"></i>Querying external diagnostic environmental coordinates...</div>`;
    sysBubble.appendChild(card);
    container.appendChild(sysBubble);

    const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&appid=${CONFIG.weatherApiKey}&units=metric`;

    fetch(url)
      .then(res => {
        if (!res.ok) throw new Error("Environmental payload fetch failure.");
        return res.json();
      })
      .then(data => {
        card.innerHTML = `
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <span style="font-size:0.58rem; font-weight:700; color:#007aff; letter-spacing:0.1em; text-transform:uppercase;">
              <i class="fa-solid fa-cloud-sun" style="margin-right:4px;"></i> ATMOSPHERIC DISPATCH
            </span>
            <span style="font-size:0.55rem; color:#666; font-family:monospace;">OWM_LIVE</span>
          </div>
          <div style="font-size:1.1rem; font-weight:700; color:#fff; margin-bottom:2px;">${data.name}, ${data.sys.country}</div>
          <div style="font-size:1.6rem; font-weight:300; color:#fff; margin:6px 0;">${Math.round(data.main.temp)}°C</div>
          <div style="font-size:0.78rem; color:#666; text-transform:capitalize; margin-bottom:8px;">Metrics // ${data.weather[0].description}</div>
          <div style="display:flex; gap:12px; font-size:0.68rem; color:#444; border-top:1px dashed #1a1a1a; padding-top:6px; font-family:monospace;">
            <span>HUMIDITY: ${data.main.humidity}%</span>
            <span>WIND: ${data.wind.speed} m/s</span>
          </div>
        `;
      })
      .catch(err => {
        card.style.borderLeft = '3px solid #ff3b5c';
        card.innerHTML = `
          <div style="font-size:0.58rem; font-weight:700; color:#ff3b5c; letter-spacing:0.1em; margin-bottom:4px;">METEOROLOGICAL ERROR</div>
          <div style="font-size:0.8rem; color:#fff;">Could not trace structural telemetry for target cluster [${city}].</div>
        `;
      });
  }

  // ========== EXPANSION WORKSPACE 4: DICTIONARY + GK MATRIX LOOKUP ==========
  function executeKnowledgeLookup(lowerQuery) {
    const container = document.getElementById('es-messages');
    
    if (KnowledgeBase.definitions[lowerQuery]) {
      renderSystemOutputCard("MATRIX DICTIONARY", KnowledgeBase.definitions[lowerQuery]);
      return true;
    }

    for (const entry of KnowledgeBase.generalKnowledge) {
      if (entry.keys.every(key => lowerQuery.includes(key))) {
        renderSystemOutputCard("INTELLIGENCE DATA DISPATCH", entry.answer);
        return true;
      }
    }

    return false;
  }

  function renderSystemOutputCard(title, dataBody) {
    const container = document.getElementById('es-messages');
    const sysBubble = document.createElement('div');
    sysBubble.className = 'es-bubble-sys';

    const card = document.createElement('div');
    card.className = 'es-result-card';
    card.style.background = '#0a0a0a';
    card.style.border = '1px solid #1a1a1a';
    card.style.borderLeft = '3px solid #007aff';
    card.style.padding = '14px';

    card.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
        <span style="font-size:0.58rem; font-weight:700; color:#007aff; letter-spacing:0.11em; text-transform:uppercase;">
          <i class="fa-solid fa-database" style="margin-right:4px;"></i> ${title}
        </span>
        <span style="font-size:0.55rem; color:#444; font-family:monospace;">LOCAL_KB</span>
      </div>
      <div style="font-size:0.84rem; color:#fff; line-height:1.5; font-weight:300;">${dataBody}</div>
    `;

    sysBubble.appendChild(card);
    container.appendChild(sysBubble);
    
    if (typeof window.scrollEsToBottom === 'function') {
      window.scrollEsToBottom();
    }
  }

